package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.contact.*;
import cn.mop.domain.contact.CustomerContact.*;
import cn.mop.domain.contact.CustomerContactRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class CustomerContactControllerTest {
    static final String ACTOR="68000000-0000-4000-8000-000000000001",TENANT="68000000-0000-4000-8000-000000000002",ID="68000000-0000-4000-8000-000000000003";
    PlatformRepository platform;CustomerContactRepository repository;CustomerContactController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(CustomerContactRepository.class);controller=new CustomerContactController(platform,repository);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",1,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(repository.create(any(),anyLong(),any())).thenAnswer(c->row(1,"CREATE",false,c.getArgument(2)));when(repository.update(any(),any(),anyLong(),any())).thenAnswer(c->row(2,"UPDATE",false,c.getArgument(3)));when(repository.restore(any(),any(),anyLong(),any())).thenAnswer(c->row(3,"RESTORE",false,c.getArgument(3)));when(repository.archive(any(),any(),anyLong())).thenReturn(row(2,"ARCHIVE",true,new CustomerContact("合成联系人",Set.of(Role.REPORTER),null,null,null,null,null,false)));}
    Access access(){return new Access(ACTOR,TENANT,1,"contact-test");}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/contacts");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","contact-test");r.addHeader("Idempotency-Key","contact-test-key");return r;}
    ObjectNode input(){var n=mapper.createObjectNode().put("expected_version",0).put("name","合成联系人").putNull("mobile").putNull("email").putNull("wecom_user_id").putNull("preferred_priorities").putNull("quiet_window").put("enabled",true);n.putArray("roles").add("REPORTER");return n;}
    Entry row(long version,String action,boolean archived,CustomerContact facts){Instant at=Instant.parse("2026-10-03T15:00:00.123Z");return new Entry(ID,TENANT,ACTOR,version,at,at,ACTOR,at,action,archived,facts);}
    CustomerContact facts(){return new CustomerContact("合成联系人",Set.of(Role.REPORTER),null,null,null,null,null,true);}
    Map<?,?> data(Object result){return (Map<?,?>)((Map<?,?>)result).get("data");}
    @Test void createExplicitUnknownsRemainUnverifiedAndNoDispatchOrIdentityGrant(){var d=data(controller.write(null,"CREATE",input(),request("POST")));assertEquals(1L,d.get("version"));assertNull(d.get("mobile"));assertNull(d.get("preferred_priorities"));assertNull(d.get("quiet_window"));assertNull(d.get("delivery_eligible"));assertEquals("NOT_VERIFIED",d.get("channel_verification"));assertEquals("CONFIG_PENDING",d.get("notification_routing_status"));assertEquals(false,d.get("identity_binding_created"));assertEquals(false,d.get("notification_dispatched"));assertEquals("Asia/Shanghai",d.get("quiet_timezone"));verify(repository).authorizeWrite(access(),null);verify(repository).create(eq(access()),eq(0L),any());}
    @Test void disabledArchiveReceiptHasFalseEligibilityAndNoPhysicalDelete(){var d=data(controller.write(ID,"ARCHIVE",mapper.createObjectNode().put("expected_version",1),request("POST")));assertEquals(true,d.get("archived"));assertEquals(false,d.get("enabled"));assertEquals(false,d.get("delivery_eligible"));assertEquals(2L,d.get("version"));verify(repository).archive(access(),ID,1);}
    @Test void updateAndRestoreRequireFullExplicitFacts(){var body=input().put("expected_version",1);controller.write(ID,"UPDATE",body,request("PATCH"));controller.write(ID,"RESTORE",body,request("POST"));verify(repository).update(eq(access()),eq(ID),eq(1L),any());verify(repository).restore(eq(access()),eq(ID),eq(1L),any());assertThrows(DomainException.class,()->controller.write(ID,"RESTORE",mapper.createObjectNode().put("expected_version",1),request("POST")));}
    @Test void tenantAdminAllowedButViewerAndEngineerFailBeforeParsing(){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"tadmin",1,true)));controller.write(null,"CREATE",input(),request("POST"));clearInvocations(repository);for(String role:List.of("viewer","msp","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,1,true)));var r=request("POST");r.setContent("not json".getBytes(StandardCharsets.UTF_8));assertEquals(403,assertThrows(DomainException.class,()->controller.create(r)).status);assertEquals(403,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);}verifyNoInteractions(repository);}
    @Test void missingInactiveOrMalformedSessionCannotRead(){var r=request("GET");r.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",1,false)));assertEquals(401,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);verifyNoInteractions(repository);}
    @Test void versionShapeMissingFieldsAndForgedVerificationRejected(){for(JsonNode v:List.of(new IntNode(1),new IntNode(-1),new TextNode("0"),new DoubleNode(0.0))){var b=input();b.set("expected_version",v);assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,"CREATE",b,request("POST"))).status);}for(String key:List.of("enabled","quiet_window","preferred_priorities","email","roles")){var b=input();b.remove(key);assertThrows(DomainException.class,()->controller.write(null,"CREATE",b,request("POST")));}assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("tenant_id",TENANT),request("POST")));assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("channel_verification","VERIFIED"),request("POST")));assertThrows(DomainException.class,()->controller.write(ID,"UPDATE",input().put("expected_version",9007199254740991L),request("PATCH")));}
    @Test void duplicateUnknownAndNullRolesOrPreferencesRejected(){for(String raw:List.of("[]","[null]","[\"REPORTER\",\"REPORTER\"]","[\"OTHER\"]","null")){var b=input();try{b.set("roles",mapper.readTree(raw));}catch(Exception e){throw new RuntimeException(e);}assertThrows(DomainException.class,()->controller.write(null,"CREATE",b,request("POST")));}for(String raw:List.of("[null]","[\"P1\",\"P1\"]","[\"P5\"]")){var b=input();try{b.set("preferred_priorities",mapper.readTree(raw));}catch(Exception e){throw new RuntimeException(e);}assertThrows(DomainException.class,()->controller.write(null,"CREATE",b,request("POST")));}}
    @Test void explicitEmptyPreferencesAndUnknownQuietGroupPreserved(){var b=input();b.putArray("preferred_priorities");b.putObject("quiet_window").putNull("enabled").putNull("start").putNull("end");var d=data(controller.write(null,"CREATE",b,request("POST")));assertEquals(List.of(),d.get("preferred_priorities"));assertNotNull(d.get("quiet_window"));assertNull(((Map<?,?>)d.get("quiet_window")).get("enabled"));}
    @Test void invalidTextChannelAndAmbiguousQuietWindowFail(){for(String value:List.of("13800000000","+0123","+1 234"))assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("mobile",value),request("POST")));assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("email","broken"),request("POST")));for(String value:List.of("24:00","7:00","12:00:01","12:00")){var b=input();b.putObject("quiet_window").put("enabled",true).put("start",value).put("end","12:00");assertThrows(DomainException.class,()->controller.write(null,"CREATE",b,request("POST")));}}
    @Test void setOrderAndObjectOrderDoNotChangeIdempotencyHash(){var one=input();one.putArray("roles").add("TECHNICAL_CONTACT").add("DECISION_MAKER");one.putArray("preferred_priorities").add("P4").add("P1");var two=one.deepCopy();two.putArray("roles").add("DECISION_MAKER").add("TECHNICAL_CONTACT");two.putArray("preferred_priorities").add("P1").add("P4");var d=data(controller.write(null,"CREATE",one,request("POST")));controller.write(null,"CREATE",two,request("POST"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(2)).idempotentAuthorized(any(),any(),any(),any(),hashes.capture(),anyLong(),any(),any());assertEquals(hashes.getAllValues().get(0),hashes.getAllValues().get(1));assertEquals(List.of("DECISION_MAKER","TECHNICAL_CONTACT"),d.get("roles"));}
    @Test void originalReceiptCallbackReauthorizesWithoutRepeatingMutation(){doAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("original",true);}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());assertEquals(true,data(controller.write(ID,"ARCHIVE",mapper.createObjectNode().put("expected_version",1),request("POST"))).get("original"));verify(repository).authorizeWrite(access(),ID);verify(repository,never()).archive(any(),any(),anyLong());}
    @Test void readonlyGetAndForeign404NeverEnterWriteTransaction(){when(repository.get(access(),ID)).thenReturn(row(1,"CREATE",false,facts()));assertEquals(ID,data(controller.get(ID,request("GET"))).get("id"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());when(repository.get(access(),ID)).thenThrow(new DomainException(404,"OBJECT_NOT_FOUND","missing"));assertEquals(404,assertThrows(DomainException.class,()->controller.get(ID,request("GET"))).status);}
    @Test void listAndHistoryUseBoundedPairedCursors(){when(repository.list(eq(access()),eq(""),eq(View.CURRENT),eq(16),isNull(),isNull())).thenReturn(Collections.nCopies(16,row(1,"CREATE",false,facts())));var page=data(controller.list(request("GET")));assertEquals(true,page.get("has_more"));assertEquals(15,((List<?>)page.get("items")).size());assertEquals(ID,page.get("next_before_id"));var bad=request("GET");bad.addParameter("before_id",ID);assertThrows(DomainException.class,()->controller.list(bad));var duplicate=request("GET");duplicate.addParameter("page_size","10","15");assertThrows(DomainException.class,()->controller.list(duplicate));var unknown=request("GET");unknown.addParameter("tenant_id",TENANT);assertThrows(DomainException.class,()->controller.list(unknown));when(repository.history(eq(access()),eq(ID),eq(16),isNull())).thenReturn(List.of());assertEquals(false,data(controller.history(ID,request("GET"))).get("has_more"));}
    @Test void boundedJsonRejectsDuplicateNestedKeysTrailingAndOversizedBeforeWrite(){for(String raw:List.of("{} {}","[[[[1]]]]","{\"enabled\":true,\"enabled\":false}","{\"quiet_window\":{\"enabled\":true,\"enabled\":false}}"," ".repeat(16385))){var r=request("POST");r.setContent(raw.getBytes(StandardCharsets.UTF_8));assertThrows(DomainException.class,()->controller.create(r));}var keyless=request("POST");keyless.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),keyless));verifyNoInteractions(repository);}
}
